import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;
import java.util.Arrays;

public class Main {
    static class FastScanner {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }

    public static void main(String[] args) {
        FastScanner fs = new FastScanner();
        String tokenN = fs.next();
        if (tokenN == null) return;

        int n = Integer.parseInt(tokenN);
        int k = fs.nextInt();

        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = fs.nextLong();
        }

        long[] b = new long[n];
        for (int i = 0; i < n; i++) {
            b[i] = fs.nextLong();
        }

        long totalNasalidade = 0;
        long[] beneficioIsencao = new long[n];

        for (int i = 0; i < n; i++) {
            totalNasalidade += Math.max(0L, a[i] - b[i]);
            beneficioIsencao[i] = Math.min(a[i], b[i]);
        }

        Arrays.sort(beneficioIsencao);

        // Podemos isentar até min(n, k + 1) sílabas
        int isencoes = Math.min(n, k + 1);
        for (int i = 0; i < isencoes; i++) {
            totalNasalidade += beneficioIsencao[n - 1 - i];
        }

        System.out.println(totalNasalidade);
    }
}
